import { Mesh, PlaneGeometry, Object3D, Vector3, Euler } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  // ---- Geometry & Material -------------------------------------------------
  const geometry = new PlaneGeometry(1, 1);
  const texture = ctx.textureLoader.load(config.assets?.imageUrl ?? '');
  const material = new MeshBasicNodeMaterial({ map: texture });

  // ---- Mesh ---------------------------------------------------------------
  const mesh = new Mesh(geometry, material);

  // ---- Transform -----------------------------------------------------------
  const pos = new Vector3(...(config.position ?? [0, 0, 0]));
  const rot = new Euler(...(config.rotation ?? [0, 0, 0]));
  const scl = new Vector3(...(config.scale ?? [1, 1, 1]));

  mesh.position.copy(pos);
  mesh.rotation.copy(rot);
  mesh.scale.copy(scl);

  // Preserve original Y for hover animation
  const originalY = mesh.position.y;

  // ---- Interaction Animations ---------------------------------------------
  let hoverTween = null;
  let pressTween = null;

  const hoverEnter = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: originalY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const hoverLeave = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: originalY,
      duration: 0.7,
      ease: 'power3.out',
    });
  };

  const pressDown = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(mesh.scale, {
      x: scl.x * 0.97,
      y: scl.y * 0.97,
      z: scl.z * 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
  };

  const pressUp = () => {
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(mesh.scale, {
      x: scl.x,
      y: scl.y,
      z: scl.z,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
  };

  const onClick = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-collection.select');
    }
  };

  // ---- Attach Handlers ----------------------------------------------------
  mesh.userData.handlers = {
    pointerover: hoverEnter,
    pointerout: hoverLeave,
    pointerdown: pressDown,
    pointerup: pressUp,
    click: onClick,
  };

  // ---- Apply Cinematic Primitives -----------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === 'function') {
        fn(mesh, prim.params);
      }
    }
  }

  // ---- Cleanup ------------------------------------------------------------
  const cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    geometry.dispose();
    material.dispose();
    // texture is managed by the loader cache; do not dispose here.
  };

  // ---- Return --------------------------------------------------------------
  const container = new Object3D();
  container.add(mesh);
  container.userData.cleanup = cleanup;
  return container;
}
